 async function loadLedger(){if(!ledgerAccount){setMessage(rtl?'اختر الحساب أولاً':'Sélectionnez un compte');return;}setBusy(true);try{setLedger(await window.hanout.accounts.ledger({accountId:Number(ledgerAccount),from,to}));}catch(e){setMessage(e.message);}finally{setBusy(false);}}
 function exportLedger(){if(!ledger)return;const esc=v=>'\"'+String(v??'').replaceAll('\"','\"\"')+'\"';const rows=[[rtl?'التاريخ':'Date',rtl?'رقم القيد':'N°',rtl?'البيان':'Libellé',rtl?'مدين':'Débit',rtl?'دائن':'Crédit',rtl?'الرصيد':'Solde'],...ledger.lines.map(x=>[x.entry_date,x.entry_no,x.description,x.debit,x.credit,x.balance])];const csv='\uFEFF'+rows.map(r=>r.map(esc).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ledger-'+ledger.account.code+'-'+from+'-'+to+'.csv';a.click();URL.revokeObjectURL(url);}
 function downloadCsv(filename,rows){const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv='\uFEFF'+rows.map(r=>r.map(esc).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function exportFinancial(){if(!financial)return;const rows=[[rtl?'التقرير المالي':'Rapport financier',from,to],[],[rtl?'ميزان المراجعة':'Balance de vérification'],[rtl?'رقم الحساب':'Code',rtl?'الحساب':'Compte',rtl?'النوع':'Type',rtl?'الرصيد':'Solde'],...financial.trial_balance.map(a=>[a.code,rtl?a.name_ar:a.name_fr,a.account_type,a.balance]),[],[rtl?'قائمة الدخل':'Compte de résultat'],[rtl?'البيان':'Libellé',rtl?'المبلغ':'Montant'],[rtl?'الإيرادات':'Produits',financial.income.revenue],[rtl?'المصاريف':'Charges',financial.income.expenses],[rtl?'صافي النتيجة':'Résultat net',financial.income.net_profit],[],[rtl?'الميزانية':'Bilan'],[rtl?'البيان':'Libellé',rtl?'المبلغ':'Montant'],[rtl?'الأصول':'Actifs',financial.balance_sheet.assets],[rtl?'الخصوم':'Passifs',financial.balance_sheet.liabilities],[rtl?'حقوق الملكية والنتيجة':'Capitaux propres et résultat',financial.balance_sheet.equity],[rtl?'فرق الميزانية':'Écart du bilan',financial.balance_sheet.difference]];downloadCsv('financial-report-'+from+'-'+to+'.csv',rows);}
 function exportJournal(){const rows=[[rtl?'رقم القيد':'N°',rtl?'التاريخ':'Date',rtl?'البيان':'Libellé',rtl?'المدين':'Débit',rtl?'الدائن':'Crédit',rtl?'المستخدم':'Utilisateur'],...entries.map(e=>[e.entry_no,e.entry_date,e.description,e.total_debit,e.total_credit,e.username||''])];downloadCsv('journal-'+from+'-'+to+'.csv',rows);}
 async function saveEntry(e){e.preventDefault();setBusy(true);setMessage('');try{const r=await window.hanout.journal.create({entry_date:entryDate,description,lines:[{account_id:Number(debitAccount),debit:Number(amount),credit:0},{account_id:Number(creditAccount),debit:0,credit:Number(amount)}]});setMessage((rtl?'تم حفظ القيد ':'Écriture enregistrée ')+r.entry_no);setDescription('');setAmount('');await load();}catch(e){setMessage(e.message);}finally{setBusy(false);}}
